// План specs/dashboard.md 3.1 (кейс DB-09). Десктоп 1440, admin, компания «test». Только просмотр (@prod-safe).
import { test, expect } from '@playwright/test';
import { ADMIN_STATE } from '../addresses/address-helpers';
import {
  PERIOD_LABEL, ROW_PREFIX, expectRowsMatchRpc, openDashboardTeam, readTeamRows, teamWidget, trackDashboardRpc,
} from './team-performance-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Дашборд, Team Performance: сумма $ и число работ у каждого техника (#5814749d)', () => {
  test('Desktop Team Performance EN: each technician row shows name, $ total and "N jobs done" for Last 30 days, sorted by total desc, equal to RPC #5814749d @desktop @prod-safe', async ({ page }) => {
    const rpc = trackDashboardRpc(page);
    await openDashboardTeam(page, 'en');
    const team = await rpc.teamFor(30);

    // Период по умолчанию — 30 дней, подпись под заголовком (комментарий программиста).
    await expect(teamWidget(page, 'en').getByText(PERIOD_LABEL.en(30), { exact: true })).toBeVisible();
    expect(team.body.length, 'в компании «test» за 30 дней есть техники с работами (иначе проверять нечего)').toBeGreaterThan(0);

    // Строки = ответ RPC: имя, сумма $, «N jobs done» («מה רצוי»: сумма за период, не только количество).
    await expectRowsMatchRpc(page, 'en', team);
    const rows = await readTeamRows(page, 'en');
    for (const r of rows) {
      const row = teamWidget(page, 'en').getByRole('button', { name: `${ROW_PREFIX.en}${r.name}`, exact: true });
      await expect(row.getByText(/^\$[\d,]+(\.\d{1,2})?$/)).toBeVisible();
      await expect(row.getByText(/^\d+ jobs? done$/)).toBeVisible();
    }

    // Рейтинг (F-46 AC 10): по сумме по убыванию; не больше 5 строк (топ-5, комментарий программиста).
    const cents = rows.map((r) => r.cents);
    expect(cents, 'сортировка по сумме по убыванию').toEqual([...cents].sort((a, b) => b - a));
    expect(rows.length).toBeLessThanOrEqual(5);
  });
});
